def p(s,cls=''):return f'<p class="{cls}">{s}</p>'
def h(s):return f'<h3>{s}</h3>'
def box(s,warn=False):return f'<div class="box{" warn" if warn else ""}">{s}</div>'
def ul(*s):return '<ul>'+''.join('<li>'+x+'</li>' for x in s)+'</ul>'
def ol(*s):return '<ol>'+''.join('<li>'+x+'</li>' for x in s)+'</ol>'
def table(headers,rows,widths=None):
 cg='<colgroup>'+''.join(f'<col style="width:{v}%">' for v in widths)+'</colgroup>' if widths else ''
 return '<table>'+cg+'<thead><tr>'+''.join('<th>'+s+'</th>' for s in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table>'
def code(s):return '<pre>'+e(s)+'</pre>'
def cols(a,b):return '<div class="two"><div>'+a+'</div><div>'+b+'</div></div>'
def refs(*s):return '<div class="refs"><b>Source trail:</b> '+ ' · '.join(e(x) for x in s)+'</div>'
