def flow(title,labels,dashed=()):
 global diagram_count;diagram_count+=1
 # Vertical flow with generous type and small source-grounded steps.
 height=len(labels)*45+10
 svg=f'<svg viewBox="0 0 680 {height}" role="img" aria-label="{e(title)}"><defs><marker id="a{diagram_count}" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#137fc0"/></marker></defs>'
 for i,label in enumerate(labels):
  y=5+i*45;dash=' stroke-dasharray="6 4"' if i in dashed else ''
  svg+=f'<rect x="14" y="{y}" width="652" height="32" rx="5" fill="#edf6fc" stroke="#1477b3"{dash}/><text x="340" y="{y+21}" text-anchor="middle" font-family="Arial" font-size="16" fill="#133b5d">{e(label)}</text>'
  if i<len(labels)-1:svg+=f'<path d="M340,{y+33} V{y+42}" stroke="#137fc0" stroke-width="2" marker-end="url(#a{diagram_count})"/>'
 return '<figure class="diagram">'+svg+'</svg><figcaption>'+e(title)+'</figcaption></figure>'
def lanes(title,rows):
 global diagram_count;diagram_count+=1
 height=len(rows)*51+8;svg=f'<svg viewBox="0 0 680 {height}" role="img" aria-label="{e(title)}">'
 for i,(left,right,status) in enumerate(rows):
  y=i*51+4;dash=' stroke-dasharray="6 4"' if status=='inactive' else ''
  for x,txt in [(5,left),(370,right)]:
   svg+=f'<rect x="{x}" y="{y}" width="300" height="39" rx="5" fill="{ "#f0f2f4" if status=="inactive" else "#edf6fc"}" stroke="#467493"{dash}/>'
   parts=txt.split('|')
   for j,t in enumerate(parts):svg+=f'<text x="{x+150}" y="{y+(24 if len(parts)==1 else 16)+j*15}" text-anchor="middle" font-family="Arial" font-size="14" fill="#173b58">{e(t)}</text>'
  svg+=f'<path d="M309,{y+21} H363 m-7,-5 l7,5 -7,5" fill="none" stroke="#137fc0" stroke-width="2"{dash}/>'
 svg+='</svg>'
 return '<figure class="diagram">'+svg+'<figcaption>'+e(title)+' Solid: implemented in the stated scope. Dashed: inactive or blocked integration.</figcaption></figure>'
def document(name,pages):
 body=''
 for i,(title,content,cls,anchor) in enumerate(pages,1):
  body+=f'<section class="page {cls}" data-page="{i}" id="{anchor}"><header><b>ASTRA</b> / {e(name)} <span style="float:right">SOURCE REVIEW · 11 NOV 2026</span></header><main class="content"><div class="eyebrow">'+('Research prototype · study edition' if i==1 else f'{name} / {i:02d}')+f'</div><h1>{title}</h1>{content}</main><footer><span>Offline research demonstration • not a certified medical system</span><span>{i} / {len(pages)}</span></footer></section>'
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>ASTRA — '+e(name)+'</title><style>'+CSS+'</style></head><body>'+body+'</body></html>'
